<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Record Fee - DormSync</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#f7f9fc;color:#172033;margin:0}main{max-width:620px;margin:auto;padding:38px 24px}.topbar{background:#fff;border-bottom:1px solid #e7ebf2;padding:18px 6%}.topbar a{color:#2563eb;text-decoration:none}.panel{background:#fff;border:1px solid #e7ebf2;border-radius:8px;padding:24px}label{display:block;font-size:13px;font-weight:600;margin:14px 0 6px}input,select,textarea,button{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:6px;font:inherit}button{margin-top:18px;background:#2563eb;color:#fff;border-color:#2563eb;font-weight:600}.error{color:#991b1b;font-size:13px}</style></head><body><header class="topbar"><a href="/warden/fees">Back to fees</a></header><main><section class="panel"><h1>Record student fee</h1><?php foreach($errors as $fieldErrors):foreach((array)$fieldErrors as $error):?><p class="error"><?=htmlspecialchars($error)?></p><?php endforeach;endforeach;?><form method="post" action="/warden/fee-store"><label>Student</label><select name="student_id" required><option value="">Select student</option><?php foreach($students as $student):?><option value="<?= (int)$student['id']?>"><?=htmlspecialchars($student['full_name'])?> (<?=htmlspecialchars($student['student_id'])?>)</option><?php endforeach;?></select><label>Amount</label><input name="amount" type="number" min="1" step="0.01" required><label>Due date</label><input name="due_date" type="date" required><label>Notes</label><textarea name="notes"></textarea><button type="submit">Record fee</button></form></section></main></body></html>
